@startuml

class Ingredient {
  + name : string
  + measuringUnit : string
  + quantityInStock : float
}

class Dish {
  + name : string
  + identifier : int
}

class DishIngredient {
  + quantity : float
}

class Table {
  + identifier : int
  + maxPeople : int
}

class Meal {
  + date : date
  + startTime : time
  + endTime : time
}

class MealDish {
  + quantity : int
}

class Waiter {
  + identifier : int
  + name : string
  + address : string
  + phoneNumber : string
}

class Client {
  + taxIdentificationNumber : string
  + name : string
  + address : string
}

Dish "1" -- "*" DishIngredient
Ingredient "1" -- "*" DishIngredient
Dish "1" -- "*" MealDish
Meal "1" -- "*" MealDish
Meal "1" -- "1" Table
Meal "0..1" -- "1" Client
Meal "*" -- "1" Waiter

@enduml

